import com.sun.fortress.runtimeSystem.BaseTask;
import com.sun.fortress.runtimeSystem.FortressExecutable;
import com.sun.fortress.runtimeSystem.Transaction;
import com.sun.fortress.runtimeSystem.TransactionAbortException;
import com.sun.fortress.compiler.runtimeValues.FRR64;
import com.sun.fortress.compiler.runtimeValues.MutableFValue;
import fortress.AnyType.Any;

import java.lang.invoke.MethodHandles;
import java.lang.invoke.VarHandle;
import java.util.Arrays;

/** Q2's model: the compiled array store of RR64 elements in two shapes, on the compiled run time's own
 *  BaseTask, task pool and Transaction.  Shape (i): one MutableFValue cell per element, read and written as
 *  the code generator reads a mutable variable (VarCodeGen.MutableStaticBinding.pushValue, assignValue).
 *  Shape (ii): a plain Object[] of elements, read and written inside a transaction through a slot API added
 *  to Transaction (an array and an index); outside one, plain or volatile. */
public class Q2Model {
    static final VarHandle AA = MethodHandles.arrayElementVarHandle(Object[].class);
    static final boolean SLOTS = hasSlots();

    static boolean hasSlots() {
        try { Transaction.class.getMethod("TXReadSlot", Object[].class, int.class); return true; }
        catch (NoSuchMethodException e) { return false; }
    }

    interface Store { double get(int i); void put(int i, double x); int size(); }

    static final class CellStore implements Store {
        final MutableFValue[] c;
        CellStore(int n) { c = new MutableFValue[n]; for (int i = 0; i < n; i++) c[i] = MutableFValue.make(FRR64.make(i)); }
        public int size() { return c.length; }
        public double get(int i) {
            Any v = BaseTask.inATransaction() ? BaseTask.getCurrentTransaction().TXRead(c[i]) : c[i].getValue();
            return ((FRR64) v).getValue();
        }
        public void put(int i, double x) {
            Any v = FRR64.make(x);
            if (BaseTask.inATransaction()) BaseTask.getCurrentTransaction().TXWrite(c[i], v); else c[i].setValue(v);
        }
    }

    static final class SlotStore implements Store {   // plain Object[] outside a transaction
        final Object[] a;
        SlotStore(int n) { a = new Object[n]; for (int i = 0; i < n; i++) a[i] = FRR64.make(i); }
        public int size() { return a.length; }
        public double get(int i) {
            Any v = BaseTask.inATransaction() ? SlotTx.read(a, i) : (Any) a[i];
            return ((FRR64) v).getValue();
        }
        public void put(int i, double x) {
            Any v = FRR64.make(x);
            if (BaseTask.inATransaction()) SlotTx.write(a, i, v); else a[i] = v;
        }
    }

    static final class SlotStoreV implements Store {  // volatile access outside a transaction, as the cell's field is
        final Object[] a;
        SlotStoreV(int n) { a = new Object[n]; for (int i = 0; i < n; i++) a[i] = FRR64.make(i); }
        public int size() { return a.length; }
        public double get(int i) {
            Any v = BaseTask.inATransaction() ? SlotTx.read(a, i) : (Any) AA.getVolatile(a, i);
            return ((FRR64) v).getValue();
        }
        public void put(int i, double x) {
            Any v = FRR64.make(x);
            if (BaseTask.inATransaction()) SlotTx.write(a, i, v); else AA.setVolatile(a, i, v);
        }
    }

    static final class Unboxed implements Store {     // decision A's double[], for scale only; no transaction
        final double[] a;
        Unboxed(int n) { a = new double[n]; for (int i = 0; i < n; i++) a[i] = i; }
        public int size() { return a.length; }
        public double get(int i) { return a[i]; }
        public void put(int i, double x) { a[i] = x; }
    }

    /** Reflection-free calls to the model's slot API; compiled against the model Transaction. */
    static final class SlotTx {
        static Any read(Object[] a, int i) { return SlotBridge.read(BaseTask.getCurrentTransaction(), a, i); }
        static void write(Object[] a, int i, Any v) { SlotBridge.write(BaseTask.getCurrentTransaction(), a, i, v); }
    }

    static double sink;

    static long readWriteOutside(Store s) {
        long t = System.nanoTime();
        for (int i = 0; i < s.size(); i++) s.put(i, s.get(i) + 1.0);
        return System.nanoTime() - t;
    }

    static long readOutside(Store s) {
        long t = System.nanoTime();
        double acc = 0;
        for (int i = 0; i < s.size(); i++) acc += s.get(i);
        sink += acc;
        return System.nanoTime() - t;
