    static long readWriteOneTransaction(Store s, int n) {
        long t = System.nanoTime();
        while (true) {
            try {
                BaseTask.startTransaction();
                for (int i = 0; i < n; i++) s.put(i, s.get(i) + 1.0);
                BaseTask.endTransaction();
                break;
            } catch (TransactionAbortException e) { BaseTask.cleanupTransaction(); }
        }
        return System.nanoTime() - t;
    }

    static long readWritePerElementTransaction(Store s, int n) {
        long t = System.nanoTime();
        for (int i = 0; i < n; i++) {
            while (true) {
                try {
                    BaseTask.startTransaction();
                    s.put(i, s.get(i) + 1.0);
                    BaseTask.endTransaction();
                    break;
                } catch (TransactionAbortException e) { BaseTask.cleanupTransaction(); }
            }
        }
        return System.nanoTime() - t;
    }

    interface Loop { long run(); }

    static double medianNsPerElement(Loop l, int n, int warm, int reps) {
        for (int k = 0; k < warm; k++) l.run();
        long[] ts = new long[reps];
        for (int k = 0; k < reps; k++) ts[k] = l.run();
        Arrays.sort(ts);
        return ts[reps / 2] / (double) n;
    }

    static long used() {
        Runtime r = Runtime.getRuntime();
        for (int k = 0; k < 4; k++) { System.gc(); try { Thread.sleep(50); } catch (InterruptedException e) { } }
        return r.totalMemory() - r.freeMemory();
    }

    interface Maker { Store make(int n); }

    static double bytesPerElement(Maker m, int n) {
        long before = used();
        Store s = m.make(n);
        long after = used();
        sink += s.get(n - 1);
        return (after - before) / (double) n;
    }

    public static void main(String[] args) throws Exception {
        final int nOut = 1_000_000, nTx = 100_000, nPer = 100_000;
        final String[] names = SLOTS ? new String[] {"cell", "slot", "slotVolatile", "unboxed"} : new String[] {"cell", "unboxed"};
