                    row[1] = medianNsPerElement(() -> readWriteOutside(sOut), nOut, 10, 15);
                    if (!(sOut instanceof Unboxed)) {
                        Store sTx = mk.make(nTx);
                        row[2] = medianNsPerElement(() -> readWriteOneTransaction(sTx, nTx), nTx, 5, 9);
                        Store sPer = mk.make(nPer);
                        row[3] = medianNsPerElement(() -> readWritePerElementTransaction(sPer, nPer), nPer, 5, 9);
                    }
